{"code": "import pytest
import impl


class TestAuthorizeBasic:
    """Test basic authorization flows."""

    def test_simple_allow(self):
        """Single matching ALLOW policy returns ALLOW."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_simple_deny(self):
        """Single matching DENY policy returns DENY."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'DENY', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_no_matching_policy_defaults_deny(self):
        """No matching policy defaults to DENY."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:bob', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_empty_policies_list_defaults_deny(self):
        """Empty policies list defaults to DENY."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        assert impl.authorize(request, []) == 'DENY'


class TestDenyOverrides:
    """Test XACML deny-overrides combining algorithm."""

    def test_deny_overrides_allow_regardless_of_order(self):
        """DENY wins over ALLOW regardless of policy order."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'},
            {'effect': 'DENY', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        ]
        assert impl.authorize(request, policies) == 'DENY'

    def test_deny_on_role_overrides_allow_on_user(self):
        """DENY on role beats ALLOW on user (ticket example: contractor scenario)."""
        request = {'subject': 'alice', 'roles': ['contractor'], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1.pdf'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1.pdf'},
            {'effect': 'DENY', 'principal': 'role:contractor', 'action': 's3:GetObject', 'resource': 'docs/reports/Q1.pdf'}
        ]
        assert impl.authorize(request, policies) == 'DENY'


class TestPrincipalMatching:
    """Test principal matching logic."""

    def test_wildcard_principal_matches_any(self):
        """Principal '*' matches any subject and roles."""
        request = {'subject': 'anyone', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': '*', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_user_principal_exact_match(self):
        """Principal 'user:<subject>' matches exact subject."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_user_principal_no_match_different_subject(self):
        """Principal 'user:bob' does not match subject 'alice'."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:bob', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_role_principal_matches_role_in_list(self):
        """Principal 'role:<name>' matches if name is in request roles."""
        request = {'subject': 'alice', 'roles': ['admin', 'contractor'], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'role:admin', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_role_principal_no_match_role_not_in_list(self):
        """Principal 'role:admin' does not match if admin not in request roles."""
        request = {'subject': 'alice', 'roles': ['contractor'], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'role:admin', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_user_principal_with_asterisk_is_literal(self):
        """Principal 'user:al*' is literal, does not match 'alice'."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:al*', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'


class TestPatternMatching:
    """Test action and resource pattern matching."""

    def test_action_prefix_match(self):
        """Action 's3:Get*' matches 's3:GetObject' via prefix."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:Get*', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_action_exact_match_required_without_star(self):
        """Action without * requires exact match."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:Get', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_resource_prefix_match(self):
        """Resource 'docs/reports/*' matches 'docs/reports/Q1.pdf' via prefix."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reports/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/*'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_resource_prefix_no_match_partial_directory(self):
        """Resource 'docs/reports/*' does not match 'docs/reportsQ1' (no slash)."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/reportsQ1'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'docs/reports/*'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_star_alone_matches_all(self):
        """Pattern '*' matches any value."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'anything/goes/here'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': '*', 'resource': '*'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_asterisk_in_middle_is_literal(self):
        """Non-final '*' is literal, 's3:*Object' does not match 's3:GetObject'."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:*Object', 'resource': 'docs/Q1.pdf'}]
        assert impl.authorize(request, policies) == 'DENY'


class TestValidation:
    """Test input validation."""

    def test_request_missing_field_raises_error(self):
        """Missing required request field raises ValueError."""
        request = {'subject': 'alice', 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}  # missing 'roles'
        policies = []
        with pytest.raises(ValueError) as exc:
