        assert 'resource' in str(exc.value).lower()

    def test_policy_invalid_effect_case_sensitive(self):
        """Effect 'Allow' (wrong case) raises ValueError with value in message."""
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'docs/Q1.pdf'}
